import Link from "next/link";
import type { OpenCompetitionOut } from "@/lib/api";
import { formatClosesAt, previewText } from "@/components/competitions/format";
import { cn } from "@/lib/utils";

type CompetitionCardProps = {
  cycle: OpenCompetitionOut;
  index?: number;
};

export function CompetitionCard({ cycle, index = 0 }: CompetitionCardProps) {
  const closes = formatClosesAt(cycle.window?.closesAt);
  const preview = previewText(cycle.description);

  return (
    <Link
      href={`/competitions/${cycle.competitionId}`}
      data-testid="competition-card"
      className={cn(
        "animate-comp-fade group relative flex min-h-[11rem] flex-col justify-between overflow-hidden rounded-2xl bg-card p-6 ring-1 ring-border transition duration-300",
        "hover:-translate-y-1 hover:ring-brand-gold/60",
        "focus-visible:ring-2 focus-visible:ring-ring",
      )}
      style={{ animationDelay: `${0.08 * index}s` }}
    >
      <span
        className="absolute inset-y-0 left-0 w-1 bg-brand-gold transition-all duration-300 group-hover:w-1.5"
        aria-hidden
      />
      <div className="space-y-3 pl-2">
        <p className="text-xs font-semibold uppercase tracking-[0.14em] text-brand-blue/70">
          Open for registration
        </p>
        <h2 className="text-xl font-bold tracking-tight text-primary transition-colors group-hover:text-brand-blue sm:text-2xl">
          {cycle.name}
        </h2>
        {preview ? (
          <p className="text-sm leading-relaxed text-muted-foreground">
            {preview}
          </p>
        ) : (
          <p className="text-sm text-muted-foreground">
            Explore skill areas and begin registration.
          </p>
        )}
      </div>
      <div className="mt-6 flex items-center justify-between gap-3 pl-2">
        {closes ? (
          <p className="text-xs text-muted-foreground">
            Closes <span className="font-medium text-foreground">{closes}</span>
          </p>
        ) : (
          <span />
        )}
        <span className="text-sm font-semibold text-primary underline-offset-4 group-hover:underline">
          View →
        </span>
      </div>
    </Link>
  );
}
